  ['Shift-Alt-ArrowUp','move-up'],['Shift-Alt-ArrowDown','move-down'],
  ['Mod-Alt-Enter','insert-above'],['Shift-Enter','insert-below'],
  ['Mod-Shift-j','join-lines'],['Mod-Alt-ArrowUp','add-cursor-up'],
  ['Mod-Alt-ArrowDown','add-cursor-down']
