  const items=[...Object.entries(WRITER_WORKSPACE_PRESETS).map(([key,p])=>({key,label:writerUi(p.labelPt,p.labelEn),values:p.values})),...this.cfg.saved.map(item=>({key:'custom:'+item.name,label:item.name,values:item.values}))];
