 if(color)symbol.style.color=color;
 try{
  const setIcon=require('obsidian').setIcon;
  if(typeof setIcon==='function')setIcon(symbol,iconName);
  else symbol.setText(item.kind==='folder'?'📁':'📄');
 }catch(_){symbol.setText(item.kind==='folder'?'📁':'📄');}
